"労働基準法第1条": [
"労働条件の原則",
"1　労働条件は、労働者が人たるに値する生活を営むための必要を充たすべきものでなければならない。\n2　この法律で定める労働条件の基準は最低のものであるから、労働関係の当事者は、この基準を理由として労働条件を低下させてはならないことはもとより、その向上を図るように努めなければならない。"
],
