"労働安全衛生規則第2条": [
"総括安全衛生管理者の選任",
"1　法第十条第一項の規定による総括安全衛生管理者の選任は、総括安全衛生管理者を選任すべき事由が発生した日から十四日以内に行なわなければならない。\n2　事業者は、総括安全衛生管理者を選任したときは、遅滞なく、情報通信技術を活用した行政の推進等に関する法律（平成十四年法律第百五十一号）第六条第一項に規定する電子情報処理組織（以下「電子情報処理組織」という。）を使用して、次に掲げる事項を、当該事業場の所在地を管轄する労働基準監督署長（以下「所轄労働基準監督署長」という。）に報告しなければならない。"
],
"労働安全衛生法第66条の8": [
"面接指導等",
"1　事業者は、その労働時間の状況その他の事項が労働者の健康の保持を考慮して厚生労働省令で定める要件に該当する労働者（次条第一項に規定する者及び第六十六条の八の四第一項に規定する者を除く。以下この条において同じ。）に対し、厚生労働省令で定めるところにより、医師による面接指導（問診その他の方法により心身の状況を把握し、これに応じて面接により必要な指導を行うことをいう。以下同じ。）を行わなければならない。\n2　労働者は、前項の規定により事業者が行う面接指導を受けなければならない。ただし、事業者の指定した医師が行う面接指導を受けることを希望しない場合において、他の医師の行う同項の規定による面接指導に相当する面接指導を受け、その結果を証明する書面を事業者に提出したときは、この限りでない。\n3　事業者は、厚生労働省令で定めるところにより、第一項及び前項ただし書の規定による面接指導の結果を記録しておかなければならない。\n4　事業者は、第一項又…"
],
