"労働安全衛生法第66条": [
"健康診断",
"1　事業者は、労働者に対し、厚生労働省令で定めるところにより、医師による健康診断（第六十六条の十第一項に規定する検査を除く。以下この条及び次条において同じ。）を行わなければならない。\n2　事業者は、有害な業務で、政令で定めるものに従事する労働者に対し、厚生労働省令で定めるところにより、医師による特別の項目についての健康診断を行なわなければならない。有害な業務で、政令で定めるものに従事させたことのある労働者で、現に使用しているものについても、同様とする。\n3　事業者は、有害な業務で、政令で定めるものに従事する労働者に対し、厚生労働省令で定めるところにより、歯科医師による健康診断を行なわなければならない。\n4　都道府県労働局長は、労働者の健康を保持するため必要があると認めるときは、労働衛生指導医の意見に基づき、厚生労働省令で定めるところにより、事業者に対し、臨時の健康診断の実施その他必要な事項を指示することができる。\n5　労働者は…"
],
