"厚生年金保険法第58条": [
"受給権者",
"1　遺族厚生年金は、被保険者又は被保険者であつた者が次の各号のいずれかに該当する場合に、その者の遺族に支給する。ただし、第一号又は第二号に該当する場合にあつては、死亡した者につき、死亡日の前日において、死亡日の属する月の前々月までに国民年金の被保険者期間があり、かつ、当該被保険者期間に係る保険料納付済期間と保険料免除期間とを合算した期間が当該被保険者期間の三分の二に満たないときは、この限りでない。\n2　前項の場合において、死亡した被保険者又は被保険者であつた者が同項第一号から第三号までのいずれかに該当し、かつ、同項第四号にも該当するときは、その遺族が遺族厚生年金を請求したときに別段の申出をした場合を除き、同項第一号から第三号までのいずれかのみに該当し、同項第四号には該当しないものとみなす。"
],
