"労働安全衛生法第61条": [
"就業制限",
"1　事業者は、クレーンの運転その他の業務で、政令で定めるものについては、都道府県労働局長の当該業務に係る免許を受けた者又は都道府県労働局長の登録を受けた者が行う当該業務に係る技能講習を修了した者その他厚生労働省令で定める資格を有する者でなければ、当該業務に就かせてはならない。\n2　前項の規定により当該業務につくことができる者以外の者は、当該業務を行なつてはならない。\n3　第一項の規定により当該業務につくことができる者は、当該業務に従事するときは、これに係る免許証その他その資格を証する書面を携帯していなければならない。\n4　職業能力開発促進法（昭和四十四年法律第六十四号）第二十四条第一項（同法第二十七条の二第二項において準用する場合を含む。）の認定に係る職業訓練を受ける労働者について必要がある場合においては、その必要の限度で、前三項の規定について、厚生労働省令で別段の定めをすることができる。"
],
"労働保険徴収法施行規則第38条": [
"労働保険料等の申告及び納付",
"1　法第十五条第一項及び第二項の申告書（次項において「概算保険料申告書」という。）、法第十六条の申告書（次項において「増加概算保険料申告書」という。）並びに確定保険料申告書は、所轄都道府県労働局歳入徴収官に提出しなければならない。\n2　前項の規定による申告書の提出は、次の区分に従い、日本銀行（本店、支店、代理店及び歳入代理店をいう。以下同じ。）、年金事務所（日本年金機構法（平成十九年法律第百九号）第二十九条の年金事務所をいう。以下同じ。）、所轄労働基準監督署長又は所轄公共職業安定所長を経由して行うことができる。\n3　労働保険料その他法の規定による徴収金は、次の区分に従い、日本銀行又は都道府県労働局労働保険特別会計収入官吏（以下「都道府県労働局収入官吏」という。）若しくは労働基準監督署労働保険特別会計収入官吏（以下「労働基準監督署収入官吏」という。）に納付しなければならない。\n4　労働保険料（印紙保険料を除く。）その他法の規定によ…"
],
