"法第二十一条の二第一項の規定による申出は、事業主の氏名又は名称及び住所又は所在地、預金口座又は貯金口座の番号及び名義人、預金又は貯金の種別並びに納付書を送付する金融機関及び店舗の名称を記載した書面を所轄都道府県労働局歳入徴収官に提出することによつて行わなければならない。"
