"労働保険徴収法第26条": [
"特例納付保険料の納付等",
"1　雇用保険法第二十二条第五項に規定する者（以下この項において「特例対象者」という。）を雇用していた事業主が、第四条の規定により雇用保険に係る保険関係が成立していたにもかかわらず、第四条の二第一項の規定による届出をしていなかつた場合には、当該事業主（当該事業主の事業を承継する者を含む。以下この条において「対象事業主」という。）は、特例納付保険料として、対象事業主が第十五条第一項の規定による納付する義務を履行していない一般保険料（同法第十四条第二項第二号に規定する厚生労働省令で定める日から当該特例対象者の離職の日までの期間に係るものであつて、その徴収する権利が時効によつて消滅しているものに限る。）の額（雇用保険率に応ずる部分の額に限る。）のうち当該特例対象者に係る額に相当する額として厚生労働省令で定めるところにより算定した額に厚生労働省令で定める額を加算した額を納付することができる。\n2　厚生労働大臣は、対象事業主に対して、特例納…"
],
"確定給付企業年金法第36条": [
"支給要件",
"1　老齢給付金は、加入者又は加入者であった者が、規約で定める老齢給付金を受けるための要件を満たすこととなったときに、その者に支給するものとする。\n2　前項に規定する規約で定める要件は、次に掲げる要件（第四十一条第二項第二号において「老齢給付金支給開始要件」という。）を満たすものでなければならない。\n3　前項第二号の政令で定める年齢は、五十歳未満であってはならない。\n4　規約において、二十年を超える加入者期間を老齢給付金の給付を受けるための要件として定めてはならない。"
],
"社会保険労務士法第25条の2": [
"不正行為の指示等を行つた場合の懲戒",
"1　厚生労働大臣は、社会保険労務士が、故意に、真正の事実に反して申請書等の作成、事務代理若しくは紛争解決手続代理業務を行つたとき、又は第十五条の規定に違反する行為をしたときは、一年以内の開業社会保険労務士若しくは開業社会保険労務士の使用人である社会保険労務士若しくは社会保険労務士法人の社員若しくは使用人である社会保険労務士の業務の停止又は失格処分の処分をすることができる。\n2　厚生労働大臣は、社会保険労務士が、相当の注意を怠り、前項に規定する行為をしたときは、戒告又は一年以内の開業社会保険労務士若しくは開業社会保険労務士の使用人である社会保険労務士若しくは社会保険労務士法人の社員若しくは使用人である社会保険労務士の業務の停止の処分をすることができる。"
],
"国民年金法施行規則第65条": [
"給付に関する通知等",
"1　厚生労働大臣は、法第十六条（法附則第九条の三の二第七項において準用する場合を含む。）の規定による受給権の裁定その他給付又は脱退一時金に関する処分を行つたときは、文書で、その内容を受給権者又は請求者に通知しなければならない。ただし、障害基礎年金の裁定請求書に併せて厚生年金保険法による障害厚生年金若しくは障害手当金又は障害共済年金若しくは障害一時金の請求書が提出された場合であつて、当該障害厚生年金若しくは障害共済年金（厚生年金保険法施行令第三条の八に定める三級の障害の状態に該当するものに限る。）又は当該障害手当金若しくは障害一時金の裁定又は支給決定が行われたときは、当該年金たる給付又は一時金の裁定又は支給決定をもつて、障害基礎年金の不支給の処分に係る通知に代えることができる。障害基礎年金の裁定請求書に併せて厚生年金保険法第二条の五第一項第二号から第四号までに定める者が支給する同法による障害厚生年金若しくは障害手当金又は障害共済年…"
],
"労働安全衛生規則第44条": [
"定期健康診断",
"1　事業者は、常時使用する労働者（第四十五条第一項に規定する労働者を除く。）に対し、一年以内ごとに一回、定期に、次の項目について医師による健康診断を行わなければならない。\n2　第一項第三号、第四号、第六号から第九号まで及び第十一号に掲げる項目については、厚生労働大臣が定める基準に基づき、医師が必要でないと認めるときは、省略することができる。\n3　第一項の健康診断は、前条、第四十五条の二又は法第六十六条第二項前段の健康診断を受けた者（前条ただし書に規定する書面を提出した者を含む。）については、当該健康診断の実施の日から一年間に限り、その者が受けた当該健康診断の項目に相当する項目を省略して行うことができる。\n4　第一項第三号に掲げる項目（聴力の検査に限る。）は、四十五歳未満の者（三十五歳及び四十歳の者を除く。）については、同項の規定にかかわらず、医師が適当と認める聴力（千ヘルツ又は四千ヘルツの音に係る聴力を除く。）の検査をもつて代え…"
],
