"健康保険法第3条": [
"定義",
"1　この法律において「被保険者」とは、適用事業所に使用される者及び任意継続被保険者をいう。ただし、次の各号のいずれかに該当する者は、日雇特例被保険者となる場合を除き、被保険者となることができない。\n2　この法律において「日雇特例被保険者」とは、適用事業所に使用される日雇労働者をいう。ただし、後期高齢者医療の被保険者等である者又は次の各号のいずれかに該当する者として厚生労働大臣の承認を受けたものは、この限りでない。\n3　この法律において「適用事業所」とは、次の各号のいずれかに該当する事業所をいう。\n4　この法律において「任意継続被保険者」とは、適用事業所に使用されなくなったため、又は第一項ただし書に該当するに至ったため被保険者（日雇特例被保険者を除く。）の資格を喪失した者であって、喪失の日の前日まで継続して二月以上被保険者（日雇特例被保険者、任意継続被保険者又は共済組合の組合員である被保険者を除く。）であったもののうち、保険者に申…"
],
"国民年金法第30条の4": [
"",
"1　疾病にかかり、又は負傷し、その初診日において二十歳未満であつた者が、障害認定日以後に二十歳に達したときは二十歳に達した日において、障害認定日が二十歳に達した日後であるときはその障害認定日において、障害等級に該当する程度の障害の状態にあるときは、その者に障害基礎年金を支給する。\n2　疾病にかかり、又は負傷し、その初診日において二十歳未満であつた者（同日において被保険者でなかつた者に限る。）が、障害認定日以後に二十歳に達したときは二十歳に達した日後において、障害認定日が二十歳に達した日後であるときはその障害認定日後において、その傷病により、六十五歳に達する日の前日までの間に、障害等級に該当する程度の障害の状態に該当するに至つたときは、その者は、その期間内に前項の障害基礎年金の支給を請求することができる。\n3　第三十条の二第三項の規定は、前項の場合に準用する。"
],
