"",
"1　賃金、労働時間その他の当該事業場における労働条件に関する事項を調査審議し、事業主に対し当該事項について意見を述べることを目的とする委員会（使用者及び当該事業場の労働者を代表する者を構成員とするものに限る。）が設置された事業場において、当該委員会がその委員の五分の四以上の多数による議決により次に掲げる事項に関する決議をし、かつ、使用者が、厚生労働省令で定めるところにより当該決議を行政官庁に届け出た場合において、第二号に掲げる労働者の範囲に属する労働者（以下この項において「対象労働者」という。）であつて書面その他の厚生労働省令で定める方法によりその同意を得たものを当該事業場における第一号に掲げる業務に就かせたときは、この章で定める労働時間、休憩、休日及び深夜の割増賃金に関する規定は、対象労働者については適用しない。ただし、第三号から第五号までに規定する措置のいずれかを使用者が講じていない場合は、この限りでない。\n2　前項の規定に…"
