"1　使用者は、就業規則の作成又は変更について、当該事業場に、労働者の過半数で組織する労働組合がある場合においてはその労働組合、労働者の過半数で組織する労働組合がない場合においては労働者の過半数を代表する者の意見を聴かなければならない。\n2　使用者は、前条の規定により届出をなすについて、前項の意見を記した書面を添付しなければならない。"
