"1　事業主は、保険年度ごとに、次に掲げる労働保険料の額その他厚生労働省令で定める事項を記載した申告書を、次の保険年度の六月一日から四十日以内（保険年度の中途に保険関係が消滅したものについては、当該保険関係が消滅した日（保険年度の中途に労災保険法第三十四条第一項の承認が取り消された事業に係る第一種特別加入保険料及び保険年度の中途に労災保険法第三十六条第一項の承認が取り消された事業に係る第三種特別加入保険料に関しては、それぞれ当該承認が取り消された日。第三項において同じ。）から五十日以内）に提出しなければならない。\n2　有期事業については、その事業主は、前項の規定にかかわらず、次に掲げる労働保険料の額その他厚生労働省令で定める事項を記載した申告書を、保険関係が消滅した日（当該保険関係が消滅した日前に労災保険法第三十四条第一項の承認が取り消された事業に係る第一種特別加入保険料に関しては、当該承認が取り消された日。次項において同じ。）か…"
