"教育訓練給付金",
"1　教育訓練給付金は、次の各号のいずれかに該当する者（以下「教育訓練給付金支給対象者」という。）が、厚生労働省令で定めるところにより、雇用の安定及び就職の促進を図るために必要な職業に関する教育訓練として厚生労働大臣が指定する教育訓練を受け、当該教育訓練を修了した場合（当該教育訓練を受けている場合であつて厚生労働省令で定める場合を含み、当該教育訓練に係る指定教育訓練実施者により厚生労働省令で定める証明がされた場合に限る。）において、支給要件期間が三年以上であるときに、支給する。\n2　前項の支給要件期間は、教育訓練給付金支給対象者が基準日までの間に同一の事業主の適用事業に引き続いて被保険者として雇用された期間（当該雇用された期間に係る被保険者となつた日前に被保険者であつたことがある者については、当該雇用された期間と当該被保険者であつた期間を通算した期間）とする。ただし、当該期間に次の各号に掲げる期間が含まれているときは、当該各号に掲…"
