"",
"1　前条第一号の事業主が、同号及び同条第二号に掲げる者を包括して当該事業について成立する保険関係に基づきこの保険による業務災害、複数業務要因災害及び通勤災害に関する保険給付を受けることができる者とすることにつき申請をし、政府の承認があつたときは、第三章第一節から第三節まで及び第三章の二の規定の適用については、次に定めるところによる。\n2　前条第一号の事業主は、前項の承認があつた後においても、政府の承認を受けて、同号及び同条第二号に掲げる者を包括して保険給付を受けることができる者としないこととすることができる。\n3　政府は、前条第一号の事業主がこの法律若しくは徴収法又はこれらの法律に基づく厚生労働省令の規定に違反したときは、第一項の承認を取り消すことができる。\n4　前条第一号及び第二号に掲げる者の保険給付を受ける権利は、第二項の規定による承認又は前項の規定による第一項の承認の取消しによつて変更されない。これらの者が同条第一号及び第…"
