"厚生年金保険法第47条の2": [
"",
"1　疾病にかかり、又は負傷し、かつ、その傷病に係る初診日において被保険者であつた者であつて、障害認定日において前条第二項に規定する障害等級（以下単に「障害等級」という。）に該当する程度の障害の状態になかつたものが、同日後六十五歳に達する日の前日までの間において、その傷病により障害等級に該当する程度の障害の状態に該当するに至つたときは、その者は、その期間内に同条第一項の障害厚生年金の支給を請求することができる。\n2　前条第一項ただし書の規定は、前項の場合に準用する。\n3　第一項の請求があつたときは、前条第一項の規定にかかわらず、その請求をした者に同項の障害厚生年金を支給する。"
],
"厚生年金保険法第47条": [
"障害厚生年金の受給権者",
"1　障害厚生年金は、疾病にかかり、又は負傷し、その疾病又は負傷及びこれらに起因する疾病（以下「傷病」という。）につき初めて医師又は歯科医師の診療を受けた日（以下「初診日」という。）において被保険者であつた者が、当該初診日から起算して一年六月を経過した日（その期間内にその傷病が治つた日（その症状が固定し治療の効果が期待できない状態に至つた日を含む。以下同じ。）があるときは、その日とし、以下「障害認定日」という。）において、その傷病により次項に規定する障害等級に該当する程度の障害の状態にある場合に、その障害の程度に応じて、その者に支給する。ただし、当該傷病に係る初診日の前日において、当該初診日の属する月の前々月までに国民年金の被保険者期間があり、かつ、当該被保険者期間に係る保険料納付済期間と保険料免除期間とを合算した期間が当該被保険者期間の三分の二に満たないときは、この限りでない。\n2　障害等級は、障害の程度に応じて重度のものから一…"
],
"国民年金法第30条": [
"支給要件",
"1　障害基礎年金は、疾病にかかり、又は負傷し、かつ、その疾病又は負傷及びこれらに起因する疾病（以下「傷病」という。）について初めて医師又は歯科医師の診療を受けた日（以下「初診日」という。）において次の各号のいずれかに該当した者が、当該初診日から起算して一年六月を経過した日（その期間内にその傷病が治つた場合においては、その治つた日（その症状が固定し治療の効果が期待できない状態に至つた日を含む。）とし、以下「障害認定日」という。）において、その傷病により次項に規定する障害等級に該当する程度の障害の状態にあるときに、その者に支給する。ただし、当該傷病に係る初診日の前日において、当該初診日の属する月の前々月までに被保険者期間があり、かつ、当該被保険者期間に係る保険料納付済期間と保険料免除期間とを合算した期間が当該被保険者期間の三分の二に満たないときは、この限りでない。\n2　障害等級は、障害の程度に応じて重度のものから一級及び二級とし、各…"
],
"労働基準法第32条の4": [
"",
"1　使用者は、当該事業場に、労働者の過半数で組織する労働組合がある場合においてはその労働組合、労働者の過半数で組織する労働組合がない場合においては労働者の過半数を代表する者との書面による協定により、次に掲げる事項を定めたときは、第三十二条の規定にかかわらず、その協定で第二号の対象期間として定められた期間を平均し一週間当たりの労働時間が四十時間を超えない範囲内において、当該協定（次項の規定による定めをした場合においては、その定めを含む。）で定めるところにより、特定された週において同条第一項の労働時間又は特定された日において同条第二項の労働時間を超えて、労働させることができる。\n2　使用者は、前項の協定で同項第四号の区分をし当該区分による各期間のうち最初の期間を除く各期間における労働日数及び総労働時間を定めたときは、当該各期間の初日の少なくとも三十日前に、当該事業場に、労働者の過半数で組織する労働組合がある場合においてはその労働組合…"
],
"労働組合法第2条": [
"労働組合",
"この法律で「労働組合」とは、労働者が主体となつて自主的に労働条件の維持改善その他経済的地位の向上を図ることを主たる目的として組織する団体又はその連合団体をいう。但し、左の各号の一に該当するものは、この限りでない。"
],
