"働き方改革推進支援助成金は、次に掲げる中小企業事業主（その資本金の額又は出資の総額が三億円（小売業又はサービス業を主たる事業とする事業主については五千万円、卸売業を主たる事業とする事業主については一億円）を超えない事業主及びその常時雇用する労働者の数が三百人（小売業を主たる事業とする事業主については五十人、卸売業又はサービス業を主たる事業とする事業主（労働基準法第百四十一条第一項に規定する医業に従事する医師が勤務する病院（医療法（昭和二十三年法律第二百五号）第一条の五第一項に規定する病院をいう。）、診療所（同条第二項に規定する診療所をいう。）、介護老人保健施設（介護保険法（平成九年法律第百二十三号）第八条第二十八項に規定する介護老人保健施設をいう。）又は介護医療院（同条第二十九項に規定する介護医療院をいう。）を営む事業主を除く。）については百人）を超えない事業主をいう。以下この条において同じ。）又は中小企業事業主の団体若しくはそ…"
