"1　事業主が、法第十九条第一項及び第二項の申告書（第三十八条において「確定保険料申告書」という。）を提出する際に、又は法第十九条第四項の規定による通知を受けた日の翌日から起算して十日以内に、それぞれ、既に納付した概算保険料の額のうち、確定保険料の額を超える額（以下「超過額」という。）の還付を請求したときは、官署支出官又は事業場の所在地を管轄する都道府県労働局労働保険特別会計資金前渡官吏（以下「所轄都道府県労働局資金前渡官吏」という。）は、その超過額を還付するものとする。事業主が、法第二十条第一項（同条第二項において準用する場合を含む。）の規定により引き下げられた労働保険料の額についての所轄都道府県労働局歳入徴収官の通知を受けた日の翌日から起算して十日以内に同条第三項の差額の還付を請求したときも、同様とする。\n2　前項の規定による請求は、次に掲げる事項を記載した請求書を官署支出官又は所轄都道府県労働局資金前渡官吏（第一条第三項第一…"
