"労働者災害補償保険法第31条": [
"",
"1　政府は、次の各号のいずれかに該当する事故について保険給付を行つたときは、厚生労働省令で定めるところにより、業務災害に関する保険給付にあつては労働基準法の規定による災害補償の価額の限度又は船員法の規定による災害補償のうち労働基準法の規定による災害補償に相当する災害補償の価額の限度で、複数業務要因災害に関する保険給付にあつては複数業務要因災害を業務災害とみなした場合に支給されるべき業務災害に関する保険給付に相当する同法の規定による災害補償の価額（当該複数業務要因災害に係る事業ごとに算定した額に限る。）の限度で、通勤災害に関する保険給付にあつては通勤災害を業務災害とみなした場合に支給されるべき業務災害に関する保険給付に相当する同法の規定による災害補償の価額の限度で、その保険給付に要した費用に相当する金額の全部又は一部を事業主から徴収することができる。\n2　政府は、療養給付を受ける労働者（厚生労働省令で定める者を除く。）から、二百円…"
],
