"有期事業の一括",
"1　法第七条第三号の厚生労働省令で定める規模以下の事業は、次の各号に該当する事業とする。\n2　法第七条第五号の厚生労働省令で定める要件は、次のとおりとする。\n3　法第七条の規定により一の事業とみなされる事業に係るこの省令の規定による事務については、前項第三号の事務所の所在地を管轄する都道府県労働局長及び労働基準監督署長を、それぞれ、所轄都道府県労働局長及び所轄労働基準監督署長とする。"
