"労働者災害補償保険法第12条の2": [
"",
"年金たる保険給付を受ける権利を有する者が死亡したためその支給を受ける権利が消滅したにもかかわらず、その死亡の日の属する月の翌月以後の分として当該年金たる保険給付の過誤払が行われた場合において、当該過誤払による返還金に係る債権（以下この条において「返還金債権」という。）に係る債務の弁済をすべき者に支払うべき保険給付があるときは、厚生労働省令で定めるところにより、当該保険給付の支払金の金額を当該過誤払による返還金債権の金額に充当することができる。"
],
"労働者災害補償保険法第11条": [
"",
"1　この法律に基づく保険給付を受ける権利を有する者が死亡した場合において、その死亡した者に支給すべき保険給付でまだその者に支給しなかつたものがあるときは、その者の配偶者（婚姻の届出をしていないが、事実上婚姻関係と同様の事情にあつた者を含む。以下同じ。）、子、父母、孫、祖父母又は兄弟姉妹であつて、その者の死亡の当時その者と生計を同じくしていたもの（遺族補償年金については当該遺族補償年金を受けることができる他の遺族、複数事業労働者遺族年金については当該複数事業労働者遺族年金を受けることができる他の遺族、遺族年金については当該遺族年金を受けることができる他の遺族）は、自己の名で、その未支給の保険給付の支給を請求することができる。\n2　前項の場合において、死亡した者が死亡前にその保険給付を請求していなかつたときは、同項に規定する者は、自己の名で、その保険給付を請求することができる。\n3　未支給の保険給付を受けるべき者の順位は、第一項に規…"
],
"労働保険徴収法第13条": [
"第一種特別加入保険料の額",
"第一種特別加入保険料の額は、労災保険法第三十四条第一項の規定により保険給付を受けることができることとされた者について同項第三号の給付基礎日額その他の事情を考慮して厚生労働省令で定める額の総額にこれらの者に係る事業についての第十二条第二項の規定による労災保険率（その率が同条第三項の規定により引き上げ又は引き下げられたときは、その引き上げ又は引き下げられた率）と同一の率から労災保険法の適用を受けるすべての事業の過去三年間の二次健康診断等給付に要した費用の額を考慮して厚生労働大臣の定める率を減じた率（以下「第一種特別加入保険料率」という。）を乗じて得た額とする。"
],
"労働者災害補償保険法第10条": [
"",
"船舶が沈没し、転覆し、滅失し、若しくは行方不明となつた際現にその船舶に乗つていた労働者若しくは船舶に乗つていてその船舶の航行中に行方不明となつた労働者の生死が三箇月間わからない場合又はこれらの労働者の死亡が三箇月以内に明らかとなり、かつ、その死亡の時期がわからない場合には、遺族補償給付、葬祭料、遺族給付及び葬祭給付の支給に関する規定の適用については、その船舶が沈没し、転覆し、滅失し、若しくは行方不明となつた日又は労働者が行方不明となつた日に、当該労働者は、死亡したものと推定する。航空機が墜落し、滅失し、若しくは行方不明となつた際現にその航空機に乗つていた労働者若しくは航空機に乗つていてその航空機の航行中行方不明となつた労働者の生死が三箇月間わからない場合又はこれらの労働者の死亡が三箇月以内に明らかとなり、かつ、その死亡の時期がわからない場合にも、同様とする。"
],
