"労働者災害補償保険法第12条の4": [
"",
"1　政府は、保険給付の原因である事故が第三者の行為によつて生じた場合において、保険給付をしたときは、その給付の価額の限度で、保険給付を受けた者が第三者に対して有する損害賠償の請求権を取得する。\n2　前項の場合において、保険給付を受けるべき者が当該第三者から同一の事由について損害賠償を受けたときは、政府は、その価額の限度で保険給付をしないことができる。"
],
"労災保険法施行規則第13条": [
"休業補償給付の請求",
"1　休業補償給付の支給を受けようとする者は、次に掲げる事項を記載した請求書を、所轄労働基準監督署長に提出しなければならない。\n2　前項第三号から第七号まで及び第九号に掲げる事項（同項第六号に掲げる事項については休業の期間に、同項第七号に掲げる事項については厚生年金保険の被保険者の資格の有無に限り、複数事業労働者に係る非災害発生事業場の事業主にあつては、同項第五号から第七号まで及び第九号に掲げる事項に限る。）については事業主の証明を、同項第六号に掲げる事項中療養の期間、傷病名及び傷病の経過については診療担当者の証明を受けなければならない。\n3　第一項第八号に規定する場合に該当するときは、当該厚生年金保険の障害厚生年金等の支給額を証明することができる書類を、同項の請求書に添えなければならない。"
],
"労働保険徴収法施行規則第18条の2": [
"法第十二条第三項の厚生労働省令で定める給付金等",
"1　法第十二条第三項の厚生労働省令で定める給付金は、労働者災害補償保険特別支給金支給規則（昭和四十九年労働省令第三十号。以下「特別支給金規則」という。）の規定による特別支給金で業務災害に係るもの（労災保険法第十六条の六第一項第二号の場合に支給される遺族補償一時金の受給権者に支給される遺族特別一時金、第十七条の二の表の第四欄に掲げる者に係るもの及び労災保険法第三十六条第一項の規定により労災保険法の規定による保険給付を受けることができることとされた者（以下「第三種特別加入者」という。）のうち労災保険法第三十三条第六号又は第七号に掲げる事業により当該業務災害が生じた場合に係るものを除く。）とする。\n2　前項の規定にかかわらず、複数事業労働者に係る特別支給金規則第六条の規定による算定基礎年額を用いて算定した特別支給金については、同一の業務上の事由について同条第一項及び第三項から第五項までの規定による算定基礎年額を三百六十五で除して得た額…"
],
"労働保険徴収法第14条": [
"第二種特別加入保険料の額",
"1　第二種特別加入保険料の額は、労災保険法第三十五条第一項の規定により労災保険の適用を受けることができることとされた者（次項において「第二種特別加入者」という。）について同条第一項第六号の給付基礎日額その他の事情を考慮して厚生労働省令で定める額の総額に労災保険法第三十三条第三号の事業と同種若しくは類似の事業又は同条第五号の作業と同種若しくは類似の作業を行う事業についての業務災害、複数業務要因災害及び通勤災害に係る災害率（労災保険法第三十五条第一項の厚生労働省令で定める者に関しては、当該同種若しくは類似の事業又は当該同種若しくは類似の作業を行う事業についての業務災害及び複数業務要因災害に係る災害率）、社会復帰促進等事業として行う事業の種類及び内容その他の事情を考慮して厚生労働大臣の定める率（以下「第二種特別加入保険料率」という。）を乗じて得た額とする。\n2　第二種特別加入保険料率は、第二種特別加入者に係る保険給付及び社会復帰促進等…"
],
