"労災保険法施行規則第11条": [
"療養の給付の方法等",
"1　法の規定による療養の給付は、法第二十九条第一項の社会復帰促進等事業として設置された病院若しくは診療所又は都道府県労働局長の指定する病院若しくは診療所、薬局若しくは訪問看護事業者（居宅を訪問することによる療養上の世話又は必要な診療の補助（以下「訪問看護」という。）の事業を行う者をいう。以下同じ。）において行う。\n2　都道府県労働局長は、療養の給付を行う病院若しくは診療所、薬局若しくは訪問看護事業者を指定し、又はその指定を取り消すときは、左に掲げる事項を公告しなければならない。\n3　第一項の都道府県労働局長の指定を受けた病院若しくは診療所、薬局又は訪問看護事業者は、それぞれ様式第一号から第四号までによる標札を見やすい場所に掲げなければならない。"
],
"労働者災害補償保険法第9条": [
"",
"1　年金たる保険給付の支給は、支給すべき事由が生じた月の翌月から始め、支給を受ける権利が消滅した月で終わるものとする。\n2　年金たる保険給付は、その支給を停止すべき事由が生じたときは、その事由が生じた月の翌月からその事由が消滅した月までの間は、支給しない。\n3　年金たる保険給付は、毎年二月、四月、六月、八月、十月及び十二月の六期に、それぞれその前月分までを支払う。ただし、支給を受ける権利が消滅した場合におけるその期の年金たる保険給付は、支払期月でない月であつても、支払うものとする。"
],
"労災保険法施行規則第49条": [
"法令の要旨等の周知",
"1　事業主は、労災保険に関する法令のうち、労働者に関係のある規定の要旨、労災保険に係る保険関係成立の年月日及び労働保険番号を、電磁的方法（電子情報処理組織を使用する方法その他の情報通信の技術を利用する方法をいう。）により提供し、又は常時事業場の見易い場所に掲示し、若しくは備え付ける等の方法によつて、労働者に周知させなければならない。\n2　事業主は、その事業についての労災保険に係る保険関係が消滅したときは、その年月日を労働者に周知させなければならない。"
],
