"労働者災害補償保険法第12条の8": [
"",
"1　第七条第一項第一号の業務災害に関する保険給付は、次に掲げる保険給付とする。\n2　前項の保険給付（傷病補償年金及び介護補償給付を除く。）は、労働基準法第七十五条から第七十七条まで、第七十九条及び第八十条に規定する災害補償の事由又は船員法（昭和二十二年法律第百号）第八十九条第一項、第九十一条第一項、第九十二条本文、第九十三条及び第九十四条に規定する災害補償の事由（同法第九十一条第一項にあつては、労働基準法第七十六条第一項に規定する災害補償の事由に相当する部分に限る。）が生じた場合に、補償を受けるべき労働者若しくは遺族又は葬祭を行う者に対し、その請求に基づいて行う。\n3　傷病補償年金は、業務上負傷し、又は疾病にかかつた労働者が、当該負傷又は疾病に係る療養の開始後一年六箇月を経過した日において次の各号のいずれにも該当するとき、又は同日後次の各号のいずれにも該当することとなつたときに、その状態が継続している間、当該労働者に対して支給す…"
],
"労働者災害補償保険法第36条": [
"",
"1　第三十三条第六号の団体又は同条第七号の事業主が、同条第六号又は第七号に掲げる者を、当該団体又は当該事業主がこの法律の施行地内において行う事業（事業の期間が予定される事業を除く。）についての保険関係に基づきこの保険による業務災害、複数業務要因災害及び通勤災害に関する保険給付を受けることができる者とすることにつき申請をし、政府の承認があつたときは、第三章第一節から第三節まで及び第三章の二の規定の適用については、次に定めるところによる。\n2　第三十四条第二項及び第三項の規定は前項の承認を受けた第三十三条第六号の団体又は同条第七号の事業主について、第三十四条第四項の規定は第三十三条第六号又は第七号に掲げる者の保険給付を受ける権利について準用する。この場合において、これらの規定中「前項の承認」とあり、及び「第一項の承認」とあるのは「第三十六条第一項の承認」と、第三十四条第二項中「同号及び同条第二号に掲げる者を包括して」とあるのは「同条…"
],
"労働者災害補償保険法第26条": [
"",
"1　二次健康診断等給付は、労働安全衛生法（昭和四十七年法律第五十七号）第六十六条第一項の規定による健康診断又は当該健康診断に係る同条第五項ただし書の規定による健康診断のうち、直近のもの（以下この項において「一次健康診断」という。）において、血圧検査、血液検査その他業務上の事由による脳血管疾患及び心臓疾患の発生にかかわる身体の状態に関する検査であつて、厚生労働省令で定めるものが行われた場合において、当該検査を受けた労働者がそのいずれの項目にも異常の所見があると診断されたときに、当該労働者（当該一次健康診断の結果その他の事情により既に脳血管疾患又は心臓疾患の症状を有すると認められるものを除く。）に対し、その請求に基づいて行う。\n2　二次健康診断等給付の範囲は、次のとおりとする。\n3　政府は、二次健康診断の結果その他の事情により既に脳血管疾患又は心臓疾患の症状を有すると認められる労働者については、当該二次健康診断に係る特定保健指導を行…"
],
