"1　療養補償給付たる療養の費用の支給を受けようとする者は、次に掲げる事項を記載した請求書を、所轄労働基準監督署長に提出しなければならない。ただし、当該者が施術所（あん摩マツサージ指圧師、はり師、きゆう師等に関する法律（昭和二十二年法律第二百十七号）第九条の二第一項の届出に係る同項の施術所及び柔道整復師法（昭和四十五年法律第十九号）第二条第二項に規定する施術所をいう。）のうち都道府県労働局長が定めるもの（以下「指名施術所」という。）において治療を受ける場合にあつては、当該請求書を、当該指名施術所を経由して所轄労働基準監督署長に提出することができる。\n2　前項第三号及び第四号に掲げる事項については事業主の証明を、同項第五号及び第六号に掲げる事項については医師その他の診療、薬剤の支給、手当又は訪問看護を担当した者（以下「診療担当者」という。）の証明を受けなければならない。ただし、看護（病院又は診療所の労働者が提供するもの及び訪問看護を…"
