"市町村長（特別区の区長を含むものとし、地方自治法（昭和二十二年法律第六十七号）第二百五十二条の十九第一項の指定都市においては、区長又は総合区長とする。）は、行政庁又は保険給付を受けようとする者に対して、当該市（特別区を含む。）町村の条例で定めるところにより、保険給付を受けようとする者又は遺族の戸籍に関し、無料で証明を行うことができる。"
