"1　法第四条の二第一項の厚生労働省令で定める事項は、次のとおりとする。\n2　法第四条の二第一項の規定による届出は、所轄労働基準監督署長又は所轄公共職業安定所長に提出することによつて行わなければならない。\n3　所轄労働基準監督署長又は所轄公共職業安定所長は、前項の届出が提出されたときであつて、必要と認めるときには、事業主に対し、登記事項証明書その他の第一項各号に掲げる事項を確認できる書類の提出を求めることができる。"
