"労災保険法施行規則第18条の2": [
"傷病補償年金の支給の決定等",
"1　業務上の事由により負傷し、又は疾病にかかつた労働者が、当該負傷又は疾病に係る療養の開始後一年六箇月を経過した日において法第十二条の八第三項各号のいずれにも該当するとき、又は同日後同項各号のいずれにも該当することとなつたときは、所轄労働基準監督署長は、当該労働者について傷病補償年金の支給の決定をしなければならない。\n2　所轄労働基準監督署長は、業務上の事由により負傷し、又は疾病にかかつた労働者の当該負傷又は疾病が療養の開始後一年六箇月を経過した日において治つていないときは、同日以後一箇月以内に、当該労働者から次に掲げる事項を記載した届書を提出させるものとする。前項の決定を行うため必要があると認めるときも、同様とする。\n3　前項の届書には、届書を提出するときにおける傷病の状態の立証に関し必要な医師又は歯科医師の診断書その他の資料を添えなければならない。\n4　第二項第四号に規定する場合に該当するときは、同項の届書には、前項の診断書…"
],
