"雇用保険法施行規則第13条": [
"被保険者の転勤の届出",
"1　事業主は、その雇用する被保険者を当該事業主の一の事業所から他の事業所に転勤させたときは、当該事実のあつた日の翌日から起算して十日以内に雇用保険被保険者転勤届（様式第十号。以下「転勤届」という。）を転勤後の事業所の所在地を管轄する公共職業安定所の長に提出しなければならない。\n2　前項の規定によりその事業所の所在地を管轄する公共職業安定所の長に提出する転勤届は、年金事務所を経由して提出することができる。\n3　事業主は、第一項の規定により提出する転勤届に労働者名簿その他の転勤の事実を証明することができる書類を添えなければならない。\n4　事業主は、前項の規定にかかわらず、職業安定局長が定めるところにより、同項に定める書類を添えないことができる。\n5　被保険者は、その雇用される事業主の一の事業所から他の事業所に転勤したときは、速やかに、被保険者証をその事業主に提示しなければならない。\n6　第一項の届出は、特定法人にあつては、転勤届及び…"
],
"雇用保険法第15条": [
"失業の認定",
"1　基本手当は、受給資格を有する者（次節から第四節までを除き、以下「受給資格者」という。）が失業している日（失業していることについての認定を受けた日に限る。以下この款において同じ。）について支給する。\n2　前項の失業していることについての認定（以下この款において「失業の認定」という。）を受けようとする受給資格者は、離職後、厚生労働省令で定めるところにより、公共職業安定所に出頭し、求職の申込みをしなければならない。\n3　失業の認定は、求職の申込みを受けた公共職業安定所において、受給資格者が離職後最初に出頭した日から起算して四週間に一回ずつ直前の二十八日の各日について行うものとする。ただし、厚生労働大臣は、公共職業安定所長の指示した公共職業訓練等（国、都道府県及び市町村並びに独立行政法人高齢・障害・求職者雇用支援機構が設置する公共職業能力開発施設の行う職業訓練（職業能力開発総合大学校の行うものを含む。）、職業訓練の実施等による特定求…"
],
