"雇用保険法第10条の3": [
"未支給の失業等給付",
"1　失業等給付の支給を受けることができる者が死亡した場合において、その者に支給されるべき失業等給付でまだ支給されていないものがあるときは、その者の配偶者（婚姻の届出をしていないが、事実上婚姻関係と同様の事情にあつた者を含む。）、子、父母、孫、祖父母又は兄弟姉妹であつて、その者の死亡の当時その者と生計を同じくしていたものは、自己の名で、その未支給の失業等給付の支給を請求することができる。\n2　前項の規定による未支給の失業等給付の支給を受けるべき者の順位は、同項に規定する順序による。\n3　第一項の規定による未支給の失業等給付の支給を受けるべき同順位者が二人以上あるときは、その一人のした請求は、全員のためその全額につきしたものとみなし、その一人に対してした支給は、全員に対してしたものとみなす。"
],
