"国民健康保険法第63条の2": [
"",
"1　市町村及び組合は、保険給付（第四十三条第三項又は第五十六条第二項の規定による差額の支給を含む。以下同じ。）を受けることができる世帯主又は組合員が保険料を滞納しており、かつ、当該保険料の納期限から厚生労働省令で定める期間が経過するまでの間に、当該市町村又は組合が保険料納付の勧奨等を行つてもなお当該保険料を納付しない場合においては、当該保険料の滞納につき災害その他の政令で定める特別の事情があると認められる場合を除き、厚生労働省令で定めるところにより、保険給付の全部又は一部の支払を一時差し止めるものとする。\n2　市町村及び組合は、前項に規定する厚生労働省令で定める期間が経過しない場合においても、保険給付を受けることができる世帯主又は組合員が、当該市町村又は組合が保険料納付の勧奨等を行つてもなお保険料を滞納している場合においては、当該保険料の滞納につき災害その他の政令で定める特別の事情があると認められる場合を除き、厚生労働省令で定め…"
],
"船員保険法第125条": [
"保険料の負担区分",
"1　被保険者（疾病任意継続被保険者、独立行政法人等職員被保険者及び後期高齢者医療の被保険者等である被保険者を除く。以下この項において同じ。）は、第百十六条第一項各号に掲げる保険料額のうち次の各号に掲げる被保険者の区分に応じ、当該各号に定める額を負担し、被保険者を使用する船舶所有者は同項各号に掲げる保険料額のうち当該被保険者が負担する額を除いた額を負担する。\n2　疾病任意継続被保険者は、第百十七条第二項の規定によりその例によるものとされた第百十六条第一項各号に掲げる被保険者の区分に応じた保険料額の全額を負担する。\n3　独立行政法人等職員被保険者については、船舶所有者が第百十六条第二項に規定する保険料額の全額を負担する。\n4　後期高齢者医療の被保険者等である被保険者については、船舶所有者が第百十六条第一項第二号に規定する保険料額の全額を負担する。"
],
