"厚生年金保険法第81条": [
"保険料",
"1　政府等は、厚生年金保険事業に要する費用（基礎年金拠出金を含む。）に充てるため、保険料を徴収する。\n2　保険料は、被保険者期間の計算の基礎となる各月につき、徴収するものとする。\n3　保険料額は、標準報酬月額及び標準賞与額にそれぞれ保険料率を乗じて得た額とする。\n4　保険料率は、次の表の上欄に掲げる月分の保険料について、それぞれ同表の下欄に定める率とする。"
],
"厚生年金保険法第24条": [
"報酬月額の算定の特例",
"1　被保険者の報酬月額が、第二十一条第一項、第二十二条第一項、第二十三条の二第一項若しくは前条第一項の規定によつて算定することが困難であるとき、又は第二十一条第一項、第二十二条第一項、第二十三条第一項、第二十三条の二第一項若しくは前条第一項の規定によつて算定した額が著しく不当であるときは、これらの規定にかかわらず、実施機関が算定する額を当該被保険者の報酬月額とする。\n2　同時に二以上の事業所で報酬を受ける被保険者について報酬月額を算定する場合においては、各事業所について、第二十一条第一項、第二十二条第一項、第二十三条第一項、第二十三条の二第一項若しくは前条第一項又は前項の規定によつて算定した額の合算額をその者の報酬月額とする。"
],
