"1　二以上の種別の被保険者であつた期間を有する者の遺族に係る遺族厚生年金（第五十八条第一項第一号から第三号までのいずれかに該当することにより支給されるものに限る。）の額については、死亡した者に係る二以上の被保険者の種別に係る被保険者であつた期間を合算し、一の期間に係る被保険者期間のみを有するものとみなして、遺族厚生年金の額の計算及びその支給停止に関する規定その他政令で定める規定を適用する。この場合において、必要な読替えその他必要な事項は、政令で定める。\n2　二以上の種別の被保険者であつた期間を有する者の遺族に係る遺族厚生年金（第五十八条第一項第四号に該当することにより支給されるものに限る。）については、各号の厚生年金被保険者期間に係る被保険者期間ごとに支給するものとし、そのそれぞれの額は、死亡した者に係る二以上の被保険者の種別に係る被保険者であつた期間を合算し、一の期間に係る被保険者期間のみを有するものとみなして、遺族厚生年金の…"
