"厚生年金保険法第34条": [
"調整期間",
"1　政府は、第二条の四第一項の規定により財政の現況及び見通しを作成するに当たり、厚生年金保険事業の財政が、財政均衡期間の終了時に保険給付の支給に支障が生じないようにするために必要な積立金（年金特別会計の厚生年金勘定の積立金及び第七十九条の二に規定する実施機関積立金をいう。）を政府等が保有しつつ当該財政均衡期間にわたつてその均衡を保つことができないと見込まれる場合には、保険給付の額を調整するものとし、政令で、保険給付の額を調整する期間（以下「調整期間」という。）の開始年度を定めるものとする。\n2　財政の現況及び見通しにおいて、前項の調整を行う必要がなくなつたと認められるときは、政令で、調整期間の終了年度を定めるものとする。\n3　政府は、調整期間において財政の現況及び見通しを作成するときは、調整期間の終了年度の見通しについても作成し、併せて、これを公表しなければならない。"
],
