"国民年金法第102条": [
"時効",
"1　年金給付を受ける権利は、その支給すべき事由が生じた日から五年を経過したとき、当該権利に基づき支払期月ごとに支払うものとされる年金給付の支給を受ける権利は、当該日の属する月の翌月以後に到来する当該年金給付の支給に係る第十八条第三項本文に規定する支払期月の翌月の初日から五年を経過したときは、時効によつて、消滅する。\n2　前項に規定する年金給付を受ける権利の時効は、当該年金給付がその全額につき支給を停止されている間は、進行しない。\n3　第一項に規定する年金給付を受ける権利又は当該権利に基づき支払期月ごとに支払うものとされる年金給付の支給を受ける権利については、会計法（昭和二十二年法律第三十五号）第三十一条の規定を適用しない。\n4　保険料その他この法律の規定による徴収金を徴収し、又はその還付を受ける権利及び死亡一時金を受ける権利は、これらを行使することができる時から二年を経過したときは、時効によつて消滅する。\n5　保険料その他この法…"
],
