"1　障害基礎年金の受給権者に対して更に障害基礎年金を支給すべき事由が生じたときは、前後の障害を併合した障害の程度による障害基礎年金を支給する。\n2　障害基礎年金の受給権者が前項の規定により前後の障害を併合した障害の程度による障害基礎年金の受給権を取得したときは、従前の障害基礎年金の受給権は、消滅する。"
