"国民年金法第36条の4": [
"",
"1　震災、風水害、火災その他これらに類する災害により、自己又は所得税法に規定する同一生計配偶者若しくは扶養親族の所有に係る住宅、家財又は政令で定めるその他の財産につき被害金額（保険金、損害賠償金等により補充された金額を除く。）がその価格のおおむね二分の一以上である損害を受けた者（以下「被災者」という。）がある場合においては、その損害を受けた月から翌年の九月までの第三十条の四の規定による障害基礎年金については、その損害を受けた年の前年又は前々年における当該被災者の所得を理由とする前条の規定による支給の停止は、行わない。\n2　前項の規定により第三十条の四の規定による障害基礎年金の支給の停止が行われなかつた場合において、当該被災者の当該損害を受けた年の所得が、その者の扶養親族等の有無及び数に応じて、前条第一項に規定する政令で定める額を超えるときは、当該被災者に支給する第三十条の四の規定による障害基礎年金で、前項に規定する期間に係るもの…"
],
"国民年金法第14条の2": [
"訂正の請求",
"1　被保険者又は被保険者であつた者は、国民年金原簿に記録された自己に係る特定国民年金原簿記録（被保険者の資格の取得及び喪失、種別の変更、保険料の納付状況その他厚生労働省令で定める事項の内容をいう。以下この項において同じ。）が事実でない、又は国民年金原簿に自己に係る特定国民年金原簿記録が記録されていないと思料するときは、厚生労働省令で定めるところにより、厚生労働大臣に対し、国民年金原簿の訂正の請求をすることができる。\n2　前項の規定は、被保険者又は被保険者であつた者が死亡した場合において、次の表の上欄に掲げる者について準用する。この場合において、同項中「自己」とあるのは、同表の上欄に掲げる者の区分に応じ、同表の下欄に掲げる字句に読み替えるものとする。"
],
