"",
"1　期間を定めて支給を停止されている障害基礎年金の受給権者に対して更に障害基礎年金を支給すべき事由が生じたときは、前条第一項の規定により支給する前後の障害を併合した障害の程度による障害基礎年金は、従前の障害基礎年金の支給を停止すべきであつた期間、その支給を停止するものとし、その間、その者に従前の障害を併合しない障害の程度による障害基礎年金を支給する。\n2　障害基礎年金の受給権者が更に障害基礎年金の受給権を取得した場合において、新たに取得した障害基礎年金が第三十六条第一項の規定によりその支給を停止すべきものであるときは、前条第二項の規定にかかわらず、その停止すべき期間、その者に対して従前の障害基礎年金を支給する。"
