"国民年金法施行規則第1条の2": [
"法第七条第一項第一号及び第三号、第八条第三号、第九条第四号並びに附則第五条第一項第一号及び第二号並びに第六項第五号、平成六年改正法附則第十一条第一項第一号及び第七項第三号、平成十六年改正法附則第二十三条第一項第一号及び第七項第三号並びに令和七年改正法附則第四十条第一項第一号及び第七項第三号に規定する厚生労働省令で定める者",
"法第七条第一項第一号及び第三号、第八条第三号、第九条第四号並びに附則第五条第一項第一号及び第二号並びに第六項第五号、国民年金法等の一部を改正する法律（平成六年法律第九十五号。以下「平成六年改正法」という。）附則第十一条第一項第一号及び第七項第三号、国民年金法等の一部を改正する法律（平成十六年法律第百四号。以下「平成十六年改正法」という。）附則第二十三条第一項第一号及び第七項第三号並びに社会経済の変化を踏まえた年金制度の機能強化のための国民年金法等の一部を改正する等の法律（令和七年法律第七十四号。以下「令和七年改正法」という。）附則第四十条第一項第一号及び第七項第三号の厚生労働省令で定める者は、次に掲げる者とする。"
],
